const queryClient = new QueryClient({ defaultOptions: { queries: { staleTime: 25_000, retry: 1 } } });
if (typeof window !== 'undefined') setAuthTokenGetter(() => localStorage.getItem('spr-token'));
const money = (value = 0) => new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' }).format(value);
const dateShort = (value?: string) => value ? new Date(value).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' }) : '—';
const assetPath = (path: string) => path.startsWith('http') ? path : `${import.meta.env.BASE_URL}${path.replace(/^\/+/, '')}`;
const imageFallback = assetPath('/goodkind-stilllife.jpg');
const USER_QUERY_KEYS = [getGetCurrentUserQueryKey(), getGetCartQueryKey(), getGetWishlistQueryKey(), getListOrdersQueryKey()];
const isUnauthorized = (error: unknown) => Boolean(error && typeof error === 'object' && 'status' in error && (error as { status?: unknown }).status === 401);
const currentReturnPath = () => `${window.location.pathname}${window.location.search}${window.location.hash}`;
const loginPath = (returnTo: string) => `/login?returnTo=${encodeURIComponent(returnTo)}`;
function authReturnPath() {
  const requested = new URLSearchParams(window.location.search).get('returnTo');
  if (!requested) return '/';
  try {
    const destination = new URL(requested, window.location.origin);
    if (destination.origin !== window.location.origin || destination.pathname === '/login' || destination.pathname === '/register') return '/';
    return `${destination.pathname}${destination.search}${destination.hash}`;
  } catch {
    return '/';
  }
}
function clearUserSession(qc: QueryClient) {
  localStorage.removeItem('spr-token');
  USER_QUERY_KEYS.forEach(queryKey => qc.removeQueries({ queryKey }));
}
function requestSignIn(qc: QueryClient, navigate: (to: string) => void, returnTo: string) {
  clearUserSession(qc);
  navigate(loginPath(returnTo));
}

